 void form(Long editId){String[] fields=page==1?new String[]{"name"}:page==2?new String[]{"title","subject","due"}:page==3?new String[]{"title","body"}:page==4?new String[]{"day","time","subject"}:new String[]{"title","subject","date"};String[] hints=page==2?new String[]{"Homework title","Subject","Due date (YYYY-MM-DD)"}:page==4?new String[]{"Day (e.g. Monday)","Time (e.g. 09:00)","Subject"}:page==5?new String[]{"Exam title","Subject","Exam date (YYYY-MM-DD)"}:fields;
 LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(22,8,22,8);EditText[] edits=new EditText[fields.length];for(int i=0;i<fields.length;i++){edits[i]=new EditText(this);edits[i].setSingleLine(!fields[i].equals("body"));edits[i].setHint(hints[i]);layout.addView(edits[i]);if((page==2 && fields[i].equals("due")) || (page==5 && fields[i].equals("date"))){final EditText dueInput=edits[i];dueInput.setFocusable(false);dueInput.setOnClickListener(v->{java.time.LocalDate initial;try{initial=java.time.LocalDate.parse(dueInput.getText().toString());}catch(Exception ex){initial=java.time.LocalDate.now();}DatePickerDialog picker=new DatePickerDialog(this,(view,year,month,day)->dueInput.setText(String.format(java.util.Locale.US,"%04d-%02d-%02d",year,month+1,day)),initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth());picker.show();});}if(page==4 && fields[i].equals("day")){final EditText dayInput=edits[i];dayInput.setFocusable(false);dayInput.setOnClickListener(v->{String[] days={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};new AlertDialog.Builder(this).setTitle("Select day").setItems(days,(d,which)->dayInput.setText(days[which])).show();});}if(page==4 && fields[i].equals("time")){final EditText timeInput=edits[i];timeInput.setFocusable(false);timeInput.setOnClickListener(v->{java.time.LocalTime initial;try{initial=java.time.LocalTime.parse(timeInput.getText().toString());}catch(Exception ex){initial=java.time.LocalTime.of(9,0);}new TimePickerDialog(this,(view,hour,minute)->timeInput.setText(String.format(java.util.Locale.US,"%02d:%02d",hour,minute)),initial.getHour(),initial.getMinute(),true).show();});}}
 if(editId!=null){try(Cursor existing=db.one(table(),editId)){if(existing.moveToFirst()){for(int i=0;i<fields.length;i++){int ix=existing.getColumnIndexOrThrow(fields[i]);edits[i].setText(existing.isNull(ix)?"":existing.getString(ix));}}}}
 AlertDialog dialog=new AlertDialog.Builder(this).setTitle((editId==null?"Add to ":"Edit ")+pages[page]).setView(layout).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{if(edits[0].getText().toString().trim().isEmpty()){edits[0].setError("Required");return;}if(page==1 && db.subjectNameExists(edits[0].getText().toString().trim(),editId==null?-1L:editId)){edits[0].setError("A subject with this name already exists");return;}ContentValues cv=new ContentValues();for(int i=0;i<fields.length;i++)cv.put(fields[i],edits[i].getText().toString().trim());if(page==2 && !edits[2].getText().toString().trim().isEmpty()){try{java.time.LocalDate.parse(edits[2].getText().toString().trim());}catch(java.time.format.DateTimeParseException ex){edits[2].setError("Use YYYY-MM-DD");return;}}if(page==5){if(edits[2].getText().toString().trim().isEmpty()){edits[2].setError("Exam date required");return;}try{java.time.LocalDate.parse(edits[2].getText().toString().trim());}catch(Exception ex){edits[2].setError("Invalid date");return;}}if(page==4){for(int i=0;i<edits.length;i++){if(edits[i].getText().toString().trim().isEmpty()){edits[i].setError("Required");return;}}try{java.time.LocalTime.parse(edits[1].getText().toString().trim());}catch(java.time.format.DateTimeParseException ex){edits[1].setError("Use HH:MM (24-hour)");return;}}if(editId==null)db.add(table(),cv);else db.update(table(),editId,cv);dialog.dismiss();show(page);}));dialog.show();}
